package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.holiday.BusinessDays;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, number, settled_due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, split_from, locked_by, late_entry, reminded_on, ref, tags, void_reason, edited_by, settle_batch, "
            // Deferred now: OPEN (or VOID, voided while deferred: it keeps showing the deferral) and
            // deferred until a date after the sheet's today.
            + "(status IN ('OPEN', 'VOID') AND deferred_until IS NOT NULL AND deferred_until > "
            + "(SELECT s.today FROM sheet s WHERE s.id = claim.sheet_id)) AS deferred, "
            // The date it rounds by: a correction's is the date of the claim it corrects.
            + "COALESCE((SELECT k.claim_date FROM claim k WHERE k.sheet_id = claim.sheet_id AND k.number = claim.corrects), "
            + "claim_date) AS round_date";

    private static final RowMapper<Claim> ROW = (rs, n) -> withSettleBatch(withEditedBy(withVoidReason(withTags(withRef(withReminded(withCorrects(new Claim(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getLong("person_id"),
            rs.getBigDecimal("amount").setScale(2).toPlainString(),
            rs.getObject("claim_date", LocalDate.class).toString(), rs.getString("note"),
            rs.getString("status"), rs.getString("number"),
            rs.getBigDecimal("settled_due") == null ? null
                    : rs.getBigDecimal("settled_due").setScale(2).toPlainString(),
            rs.getString("opened_by"), rs.getBoolean("stated"),
            rs.getBigDecimal("stated_due") == null ? null
                    : rs.getBigDecimal("stated_due").setScale(2).toPlainString()), rs.getString("corrects"),
            rs.getObject("round_date", LocalDate.class).toString(),
            rs.getObject("due_by", LocalDate.class).toString(),
            rs.getObject("deferred_until", LocalDate.class), rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"), rs.getString("locked_by"), rs.getBoolean("late_entry")),
            rs.getObject("reminded_on", LocalDate.class)), rs.getString("ref")), rs.getString("tags")), rs.getString("void_reason")), rs.getString("edited_by")), rs.getObject("settle_batch", Integer.class));

    private static Claim withSettleBatch(Claim claim, Integer settleBatch) {
        claim.setSettleBatch(settleBatch);
        return claim;
    }

    private static Claim withEditedBy(Claim claim, String editedBy) {
        claim.setEditedBy(editedBy);
        return claim;
    }

    private static Claim withVoidReason(Claim claim, String voidReason) {
        claim.setVoidReason(voidReason);
        return claim;
    }

    private static Claim withTags(Claim claim, String tags) {
        claim.setTags(tags);
        return claim;
    }

    private static Claim withRef(Claim claim, String ref) {
        claim.setRef(ref);
        return claim;
    }

    private static Claim withReminded(Claim claim, LocalDate reminded) {
        claim.setReminded(reminded == null ? null : reminded.toString());
        return claim;
    }

    private static Claim withCorrects(Claim claim, String corrects, String roundDate, String dueBy,
            LocalDate deferredUntil, boolean deferred, int proofs, String splitFrom, String lockedBy, boolean lateEntry) {
        claim.setLateEntry(lateEntry);
        claim.setLockedBy(lockedBy);
        claim.setSplitFrom(splitFrom);
        claim.setProofs(proofs);
        claim.setCorrects(corrects);
        claim.setDeferral(deferredUntil == null ? null : deferredUntil.toString(), deferred);
        claim.setDueBy(dueBy);
        claim.setRoundDate(roundDate);
        return claim;
    }

    /** The next place in a sheet's list (newest first); takes the sheet id as its parameter. */
    private static final String NEXT_SEQ = "(SELECT COALESCE(MAX(k.list_seq), 0) + 1 FROM claim k WHERE k.sheet_id = ?)";

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY list_seq DESC, id DESC",
                ROW, sheetId);
    }

    public Claim find(String sheetId, long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id).stream().findFirst().orElse(null);
    }

    /** The claim on the sheet with that number; null when none has it. */
    public Claim findByNumber(String sheetId, String number) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND number = ?",
                ROW, sheetId, number).stream().findFirst().orElse(null);
    }

    /** Add a claim with its due-by, fixed now. */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, LocalDate dueBy, String user) {
        return add(sheetId, personId, amount, date, note, corrects, dueBy, user, null);
    }

    /** Add a claim with its due-by, fixed now, and its reference (null: none; see {@link #requireRefFree}). */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, LocalDate dueBy, String user, String ref) {
        return add(sheetId, personId, amount, date, note, corrects, dueBy, user, ref, null);
    }

    /** Add a claim with its due-by, fixed now, its reference and its tags (null: none; see {@link ClaimForm#tags}). */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, LocalDate dueBy, String user, String ref, String tags) {
        // The terms it is fixed with: the business days up to its due-by, past the sheet's holidays now.
        int terms = BusinessDays.between(date, dueBy, holidays(sheetId));
        GeneratedKeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, created_by, corrects, due_by, ref, ref_key, tags, terms) "
                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setObject(4, date);
            ps.setString(5, note);
            ps.setString(6, user);
            ps.setObject(7, corrects);
            ps.setObject(8, dueBy);
            ps.setString(9, ref);
            ps.setString(10, refKey(ref));
            ps.setString(11, tags);
            ps.setInt(12, terms);
            return ps;
        }, key);
        long id = key.getKey().longValue();
        jdbc.update("UPDATE claim SET list_seq = " + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?", sheetId, sheetId, id);
        snapshot(sheetId, id);
        useTags(sheetId, tags);
        return find(sheetId, id);
    }

    /** A reference compared without regard to case (null: none). */
    private static String refKey(String ref) {
        return ref == null ? null : ref.toLowerCase(Locale.ROOT);
    }

    /** Refuse a reference (null: none, always free) that a claim on the sheet other than {@code exceptId}
     *  (0: none) already has, compared without regard to case. */
    public void requireRefFree(String sheetId, String ref, long exceptId) throws InvalidClaimException {
        if (ref == null) return;
        Integer used = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND ref_key = ? AND id <> ?",
                Integer.class, sheetId, refKey(ref), exceptId);
        if (used != null && used > 0) {
            throw new InvalidClaimException("The reference is already used on the sheet: " + ref);
        }
    }

    public void update(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ?, corrects = ?, ref = ?, ref_key = ?, tags = ?, void_reason = ?, edited_by = ?, settle_batch = ? WHERE sheet_id = ? AND id = ?",
                new BigDecimal(claim.getAmount()), LocalDate.parse(claim.getDate()), claim.getNote(),
                claim.getStatus(), claim.getNumber(),
                claim.getSettledDue() == null ? null : new BigDecimal(claim.getSettledDue()),
                claim.getOpenedBy(), claim.getCorrects(), claim.getRef(), refKey(claim.getRef()), claim.getTags(),
                claim.getVoidReason(), claim.getEditedBy(), claim.getSettleBatch(), claim.getSheetId(), claim.getId());
        snapshot(claim.getSheetId(), claim.getId());
        useTags(claim.getSheetId(), claim.getTags());
    }

    /** Keep each of the tags (comma separated; null: none) among those ever used on the sheet. */
    private void useTags(String sheetId, String tags) {
        if (tags == null) return;
        for (String tag : tags.split(",")) {
            jdbc.update("MERGE INTO sheet_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", sheetId, tag);
        }
    }

    /** Every tag ever used on the sheet, sorted. */
    public List<String> tags(String sheetId) {
        return jdbc.queryForList("SELECT tag FROM sheet_tag WHERE sheet_id = ? ORDER BY tag", String.class, sheetId);
    }

    /** Save a claim moved to another person: its person, its number (renumbered), its binding
     *  (dropped), and its place in the list, now the newest. */
    public void reassign(Claim claim) {
        jdbc.update("UPDATE claim SET person_id = ?, number = ?, stated = ?, stated_due = ?, list_seq = "
                + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?",
                claim.getPersonId(), claim.getNumber(), claim.isStated(),
                claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
                claim.getSheetId(), claim.getSheetId(), claim.getId());
        snapshot(claim.getSheetId(), claim.getId());
    }

    /** Move every claim of the person {@code fromId} to {@code intoId}, in the order they were added,
     *  each the newest in the list as it moves: their numbers and dates kept, and any figure a statement
     *  bound them to kept. */
    public void moveAll(String sheetId, long fromId, long intoId) {
        for (Long id : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                Long.class, sheetId, fromId)) {
            jdbc.update("UPDATE claim SET person_id = ?, list_seq = "
                    + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?", intoId, sheetId, sheetId, id);
            snapshot(sheetId, id);
        }
    }

    /** Move every claim of the person to the sheet {@code to}, with their logs, comments and history,
     *  keeping their order in the list (each newer than the other sheet's): their status, dates, notes,
     *  tags, frozen figures and any figure a statement bound them to kept, their reference, lock and
     *  settle batch dropped, and their numbers taken away. The ids of those that had a number come back in
     *  the order they were opened (by the sheet's today then, then the order they were added), for
     *  {@link #renumber}. */
    public List<Long> transferAll(String sheetId, long personId, String to) {
        List<Long> numbered = jdbc.queryForList("SELECT c.id FROM claim c WHERE c.sheet_id = ? AND c.person_id = ? "
                + "AND c.number IS NOT NULL ORDER BY COALESCE((SELECT MIN(l.on_date) FROM claim_log l WHERE "
                + "l.claim_id = c.id AND l.status = 'OPEN'), (SELECT MIN(l.on_date) FROM claim_log l WHERE "
                + "l.claim_id = c.id AND l.status <> 'DRAFT'), c.claim_date), c.id", Long.class, sheetId, personId);
        long seq = jdbc.queryForObject("SELECT COALESCE(MAX(list_seq), 0) FROM claim WHERE sheet_id = ?", Long.class, to);
        for (Long id : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY list_seq, id",
                Long.class, sheetId, personId)) {
            jdbc.update("UPDATE claim SET sheet_id = ?, list_seq = ?, number = NULL, "
                    + "ref = NULL, ref_key = NULL, locked_by = NULL, settle_batch = NULL WHERE sheet_id = ? AND id = ?",
                    to, ++seq, sheetId, id);
            for (String table : List.of("claim_log", "claim_comment", "claim_line", "claim_history")) {
                jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND claim_id = ?", to, sheetId, id);
            }
            snapshot(to, id);
            useTags(to, jdbc.queryForObject("SELECT tags FROM claim WHERE id = ?", String.class, id));
        }
        return numbered;
    }

    /** Give a transferred claim its number on its new sheet. */
    public void renumber(Claim claim, String number) {
        jdbc.update("UPDATE claim SET number = ? WHERE sheet_id = ? AND id = ?", number, claim.getSheetId(), claim.getId());
        claim.setNumber(number);
    }

    /** Save a re-dated claim: its date (its due-by, period and number stay). */
    public void redate(Claim claim) {
        jdbc.update("UPDATE claim SET claim_date = ?, number = ? WHERE sheet_id = ? AND id = ?",
                LocalDate.parse(claim.getDate()), claim.getNumber(), claim.getSheetId(), claim.getId());
        snapshot(claim.getSheetId(), claim.getId());
    }

    /** Work out again, after a holiday was added, the due-by of every claim on the sheet that is not
     *  SETTLED or VOID and is due by the holiday or later: from its date, with the terms it was fixed
     *  with, past the sheet's holidays now. A claim whose due-by moves is kept in its history. */
    public void refixDueBys(String sheetId, LocalDate holiday) {
        Set<LocalDate> holidays = holidays(sheetId);
        jdbc.query("SELECT id, claim_date, terms, due_by FROM claim WHERE sheet_id = ? "
                + "AND status NOT IN ('SETTLED', 'VOID', 'DELETED') AND due_by >= ? ORDER BY id", (rs) -> {
                    long id = rs.getLong("id");
                    LocalDate dueBy = BusinessDays.dueBy(rs.getObject("claim_date", LocalDate.class),
                            rs.getInt("terms"), holidays);
                    if (!dueBy.equals(rs.getObject("due_by", LocalDate.class))) {
                        jdbc.update("UPDATE claim SET due_by = ? WHERE sheet_id = ? AND id = ?", dueBy, sheetId, id);
                        snapshot(sheetId, id);
                    }
                }, sheetId, holiday);
    }

    private Set<LocalDate> holidays(String sheetId) {
        return new HashSet<>(jdbc.queryForList("SELECT holiday FROM holiday WHERE sheet_id = ?", LocalDate.class, sheetId));
    }

    /** The person's claims, newest first. */
    public List<Claim> listOf(String sheetId, long personId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY list_seq DESC, id DESC",
                ROW, sheetId, personId);
    }

    /** Keep the claim as it stands now in its history, with the sheet's today. */
    private void snapshot(String sheetId, long id) {
        jdbc.update("INSERT INTO claim_history (sheet_id, claim_id, on_date, person_id, amount, claim_date, status, "
                + "settled_due, stated, stated_due, deferred_until, due_by) SELECT c.sheet_id, c.id, s.today, c.person_id, "
                + "c.amount, c.claim_date, c.status, c.settled_due, c.stated, c.stated_due, c.deferred_until, c.due_by "
                + "FROM claim c JOIN sheet s ON s.id = c.sheet_id WHERE c.sheet_id = ? AND c.id = ?", sheetId, id);
    }

    /** The person's claims as they stood at the end of the date, newest first: each as its last change
     *  made while the sheet's today was on or before the date left it (a claim of theirs then, and only
     *  claims there were then), deferred when OPEN and deferred until after the date. */
    public List<Claim> listOfAsOf(String sheetId, long personId, LocalDate asOf) {
        return jdbc.query("SELECT h.claim_id, h.person_id, h.amount, h.claim_date, h.status, h.settled_due, h.stated, "
                + "h.stated_due, h.deferred_until, h.due_by, c.note, c.ref, c.tags, c.number, c.opened_by, c.corrects, "
                + "COALESCE((SELECT k.claim_date FROM claim k WHERE k.sheet_id = c.sheet_id AND k.number = c.corrects), "
                + "h.claim_date) AS round_date FROM claim_history h JOIN claim c ON c.id = h.claim_id "
                + "WHERE h.sheet_id = ? AND h.person_id = ? AND h.id = (SELECT MAX(h2.id) FROM claim_history h2 "
                + "WHERE h2.claim_id = h.claim_id AND (h2.on_date IS NULL OR h2.on_date <= ?)) "
                + "ORDER BY c.list_seq DESC, c.id DESC", (rs, n) -> {
                    BigDecimal settled = rs.getBigDecimal("settled_due");
                    BigDecimal stated = rs.getBigDecimal("stated_due");
                    LocalDate until = rs.getObject("deferred_until", LocalDate.class);
                    String status = rs.getString("status");
                    Claim claim = new Claim(rs.getLong("claim_id"), sheetId, rs.getLong("person_id"),
                            rs.getBigDecimal("amount").setScale(2).toPlainString(),
                            rs.getObject("claim_date", LocalDate.class).toString(), rs.getString("note"), status,
                            rs.getString("number"), settled == null ? null : settled.setScale(2).toPlainString(),
                            rs.getString("opened_by"), rs.getBoolean("stated"),
                            stated == null ? null : stated.setScale(2).toPlainString());
                    claim.setRef(rs.getString("ref"));
                    claim.setTags(rs.getString("tags"));
                    return withCorrects(claim, rs.getString("corrects"),
                            rs.getObject("round_date", LocalDate.class).toString(),
                            rs.getObject("due_by", LocalDate.class).toString(), until,
                            ClaimStatus.OPEN.name().equals(status) && until != null && until.isAfter(asOf),
                            0, null, null, false);
                }, sheetId, personId, asOf);
    }

    /** Save the date a claim is deferred until. */
    public void updateDeferral(Claim claim) {
        jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet_id = ? AND id = ?",
                claim.getDeferredUntil() == null ? null : LocalDate.parse(claim.getDeferredUntil()),
                claim.getSheetId(), claim.getId());
        snapshot(claim.getSheetId(), claim.getId());
    }

    /** Save the date a claim was last reminded on. */
    public void updateReminded(Claim claim) {
        jdbc.update("UPDATE claim SET reminded_on = ? WHERE sheet_id = ? AND id = ?",
                claim.getReminded() == null ? null : LocalDate.parse(claim.getReminded()),
                claim.getSheetId(), claim.getId());
    }

    /** Save the number of the claim a claim was split from. */
    public void updateSplitFrom(Claim claim) {
        jdbc.update("UPDATE claim SET split_from = ? WHERE sheet_id = ? AND id = ?",
                claim.getSplitFrom(), claim.getSheetId(), claim.getId());
    }

    /** Save a claim's proofs count. */
    public void updateProofs(Claim claim) {
        jdbc.update("UPDATE claim SET proofs = ? WHERE sheet_id = ? AND id = ?",
                claim.getProofs(), claim.getSheetId(), claim.getId());
    }

    /** Save a claim's binding by its person's last statement. */
    public void updateBinding(Claim claim) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
                claim.isStated(), claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
                claim.getSheetId(), claim.getId());
        snapshot(claim.getSheetId(), claim.getId());
    }

    /** The next claim number in the sequence shared by the sheets of a tree ({@code tree}, the sheet
     *  among them): one after the last number given on any of them. The tree's root is locked first so
     *  two claims opened at the same moment anywhere in the tree never get the same one; rolled back
     *  with the request when it is refused. */
    public String nextNumber(String sheetId, java.util.List<String> tree) {
        jdbc.queryForList("SELECT id FROM sheet WHERE id = ? FOR UPDATE", String.class, tree.get(0));
        String in = String.join(", ", java.util.Collections.nCopies(tree.size(), "?"));
        java.util.List<Object> args = new java.util.ArrayList<>(tree);
        args.add(sheetId);
        return String.valueOf(jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE ("
                + "UPDATE sheet SET last_claim_number = (SELECT COALESCE(MAX(last_claim_number), 0) FROM sheet "
                + "WHERE id IN (" + in + ")) + 1 WHERE id = ?)", Long.class, args.toArray()));
    }

    /** The next claim number in fiscal year {@code fy}'s sequence shared by the sheets of a tree
     *  ({@code FY<yyyy>-<n>}, from 1; {@code tree}, the sheet among them): one after the last number of
     *  that fiscal year given on any of them, taken under the same lock as {@link #nextNumber}. */
    public String nextFiscalYearNumber(String sheetId, java.util.List<String> tree, String fy) {
        jdbc.queryForList("SELECT id FROM sheet WHERE id = ? FOR UPDATE", String.class, tree.get(0));
        try {
            jdbc.update("INSERT INTO sheet_fy_number (sheet_id, fy) SELECT ?, ? WHERE NOT EXISTS "
                    + "(SELECT 1 FROM sheet_fy_number WHERE sheet_id = ? AND fy = ?)", sheetId, fy, sheetId, fy);
        } catch (DuplicateKeyException raced) {
            // Another request started the sequence at the same moment.
        }
        String in = String.join(", ", java.util.Collections.nCopies(tree.size(), "?"));
        java.util.List<Object> args = new java.util.ArrayList<>();
        args.add(fy);
        args.addAll(tree);
        args.add(sheetId);
        args.add(fy);
        Long n = jdbc.queryForObject("SELECT last_number FROM FINAL TABLE ("
                + "UPDATE sheet_fy_number SET last_number = (SELECT COALESCE(MAX(last_number), 0) FROM sheet_fy_number "
                + "WHERE fy = ? AND sheet_id IN (" + in + ")) + 1 WHERE sheet_id = ? AND fy = ?)", Long.class, args.toArray());
        return fy + "-" + n;
    }

    /** The next number in a period's own sequence on the sheet ({@code <period>-<n>}, from 1), or
     *  for a claim in no period ({@code period} null) in the X sequence ({@code X-<n>}); taken
     *  atomically as {@link #nextNumber} is. */
    public String nextPeriodNumber(String sheetId, String period) {
        String key = period == null ? "" : period;
        try {
            jdbc.update("INSERT INTO sheet_period_number (sheet_id, period_key) SELECT ?, ? WHERE NOT EXISTS "
                    + "(SELECT 1 FROM sheet_period_number WHERE sheet_id = ? AND period_key = ?)",
                    sheetId, key, sheetId, key);
        } catch (DuplicateKeyException raced) {
            // Another request started the sequence at the same moment.
        }
        Long n = jdbc.queryForObject("SELECT last_number FROM FINAL TABLE (UPDATE sheet_period_number "
                + "SET last_number = last_number + 1 WHERE sheet_id = ? AND period_key = ?)",
                Long.class, sheetId, key);
        return (period == null ? "X" : period) + "-" + n;
    }

    /** Mark a claim as a late entry: added while the period its due-by falls in was soft-closed. */
    public void markLateEntry(Claim claim) {
        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet_id = ? AND id = ?", claim.getSheetId(), claim.getId());
        claim.setLateEntry(true);
    }

    /** Lock a claim for the user opening its editor, releasing any other claim of the same person that
     *  user held. */
    public void lock(Claim claim, String user) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND person_id = ? AND locked_by = ? AND id <> ?",
                claim.getSheetId(), claim.getPersonId(), user, claim.getId());
        jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet_id = ? AND id = ?", user, claim.getSheetId(), claim.getId());
        claim.setLockedBy(user);
    }

    /** Release a claim's lock when {@code user} holds it (null: whoever holds it). */
    public void unlock(Claim claim, String user) {
        if (user == null || user.equals(claim.getLockedBy())) {
            jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND id = ?", claim.getSheetId(), claim.getId());
            claim.setLockedBy(null);
        }
    }

    /** Release every claim lock on the sheet. */
    public void unlockAll(String sheetId) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
    }
}

package net.officefloor.hq.app.person;

import com.fasterxml.jackson.annotation.JsonIgnore;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and their grades (A, B or C), each in force from its from-date (the
 *  first from the beginning of time), with {@code grade} the one in force on the sheet's today, the version raised by each saved edit, and
 *  their statements: how many have been taken, and the last one's due-total and date (none until the
 *  first), and the date they are retired from (null: not retired; set at all, they count as retired),
 *  and their holds, by when they were added (their OPEN claims dated within one, and not bound by a
 *  statement, count in no live total; nor, from their retirement date on, do any of their open ones). */
public class Person {
    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    /** The grades they were given, by from-date (none first). */
    private java.util.List<GradeFrom> grades = new java.util.ArrayList<>();
    /** The grade this request's save records (null: none). */
    private GradeFrom recorded;
    /** Their own terms in whole days (null: none). */
    private Integer terms;
    /** Whether this request's save changed their terms, for its audit line. */
    private boolean termsChanged;
    /** Their contact, trimmed and lower-cased (null: none). */
    private String contact;
    /** Whether this request's save changed their contact, for its audit line. */
    private boolean contactChanged;
    /** Their tags, sorted and comma separated (null: none). */
    private String tags;
    private long version;
    private int statementCount;
    private String statedTotal;
    private String statementDate;
    private String retiredFrom;
    /** Their past retirements, oldest first. */
    private java.util.List<Retirement> retirements = new java.util.ArrayList<>();
    /** The SNAPSHOTs written for them, oldest first. */
    private java.util.List<Snapshot> snapshots = new java.util.ArrayList<>();
    /** Their holds, in the order they were added. */
    private java.util.List<Hold> holds = new java.util.ArrayList<>();
    /** The sheet's today (null: not known). */
    private java.time.LocalDate today;
    /** The ids of the people they name as patrons, in the order named. */
    private java.util.List<Long> patronIds = new java.util.ArrayList<>();
    /** Their aliases, sorted as names are compared. */
    private java.util.List<String> aliases = new java.util.ArrayList<>();
    /** The date the statement this request took was taken as of (null: now), for its audit line. */
    private String statedAsOf;
    /** How many claims the statement this request took bound, for its audit line. */
    private int statedClaims;
    /** The due-total of the statement this request cancelled, for its audit line. */
    private String cancelledTotal;

    public Person(long id, String sheetId, String name, String grade, long version) {
        this(id, sheetId, name, grade, version, 0, null, null);
    }

    public Person(long id, String sheetId, String name, String grade, long version,
            int statementCount, String statedTotal, String statementDate) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
        this.statementCount = statementCount;
        this.statedTotal = statedTotal;
        this.statementDate = statementDate;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getGrade() { return grade; }
    public java.util.List<GradeFrom> getGrades() { return grades; }

    /** Their grades, by from-date (none first), and the one in force on the sheet's today. */
    public void setGrades(java.util.List<GradeFrom> grades, java.time.LocalDate today) {
        this.grades = grades;
        this.grade = gradeOn(today.toString());
        this.today = today;
    }

    /** The grade in force on the date (yyyy-MM-dd): the one with the latest from-date on or before
     *  it; null when there is none. */
    public String gradeOn(String date) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && g.from().compareTo(date) > 0) continue;
            if (found == null || (found.from() == null ? "" : found.from()).compareTo(g.from() == null ? "" : g.from()) < 0) found = g;
        }
        return found == null ? null : found.grade();
    }

    /** Give them the grade from the from-date (null: the beginning of time), replacing the one
     *  with the same from-date; the save records it. */
    public void giveGrade(String grade, String from, java.time.LocalDate today) {
        java.util.List<GradeFrom> now = new java.util.ArrayList<>(grades);
        now.removeIf((g) -> java.util.Objects.equals(g.from(), from));
        now.add(new GradeFrom(grade, from));
        now.sort(java.util.Comparator.comparing((GradeFrom g) -> g.from() == null ? "" : g.from()));
        setGrades(now, today);
        recorded = new GradeFrom(grade, from);
    }

    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }

    /** Give them these terms (null: none); the audit line records them when they changed. */
    public void giveTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }

    @JsonIgnore
    public boolean isTermsChanged() { return termsChanged; }

    public String getContact() { return contact; }
    public void setContact(String contact) { this.contact = contact; }

    /** Give them this contact (null: none); the audit line records it when it changed. */
    public void giveContact(String contact) {
        contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }

    @JsonIgnore
    public boolean isContactChanged() { return contactChanged; }

    /** Their tags, sorted and comma separated (null: none). */
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }

    @JsonIgnore
    public GradeFrom getRecorded() { return recorded; }
    public long getVersion() { return version; }
    public void setVersion(long version) { this.version = version; }
    public int getStatementCount() { return statementCount; }
    public String getStatedTotal() { return statedTotal; }
    public String getStatementDate() { return statementDate; }
    public String getRetiredFrom() { return retiredFrom; }
    public void setRetiredFrom(String retiredFrom) { this.retiredFrom = retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    public java.util.List<Retirement> getRetirements() { return retirements; }
    public void setRetirements(java.util.List<Retirement> retirements) { this.retirements = retirements; }
    public java.util.List<Snapshot> getSnapshots() { return snapshots; }
    public void setSnapshots(java.util.List<Snapshot> snapshots) { this.snapshots = snapshots; }

    /** Unretire them on the date: no longer retired, the retirement kept as a past one up to it. */
    public void unretire(String on) {
        retirements.add(new Retirement(retiredFrom, on));
        retiredFrom = null;
    }
    /** Whether the sheet's today is on or after their retirement date: their open claims no statement
     *  bound then count in no live total. */
    public boolean isRetiredReached() {
        return retiredFrom != null && today != null && !today.isBefore(java.time.LocalDate.parse(retiredFrom));
    }
    /** Whether they have any hold. */
    public boolean isHeld() { return !holds.isEmpty(); }
    public java.util.List<Hold> getHolds() { return holds; }
    public void setHolds(java.util.List<Hold> holds) { this.holds = holds; }
    public java.util.List<Long> getPatronIds() { return patronIds; }
    public void setPatronIds(java.util.List<Long> patronIds) { this.patronIds = patronIds; }
    public java.util.List<String> getAliases() { return aliases; }
    public void setAliases(java.util.List<String> aliases) { this.aliases = aliases; }
    /** The sheet they were last transferred from (null: none). */
    private String origin;
    public String getOrigin() { return origin; }
    public void setOrigin(String origin) { this.origin = origin; }
    /** Whether their name or an alias is used, as a name or alias, on another sheet of the sheet's tree. */
    private boolean clashing;
    public boolean isClashing() { return clashing; }
    public void setClashing(boolean clashing) { this.clashing = clashing; }

    /** Whether the claim counts in live totals: it counts by status, and is not an open (OPEN or
     *  PENDING) claim dated within one of their holds, or of a person whose retirement date is reached,
     *  that no statement bound, nor a deferred one. */
    public boolean countsLive(Claim claim) {
        return claim.isCounting() && !leftOutLive(claim);
    }

    /** Whether the live rules leave the claim out whatever its status counts: it is deferred, or an
     *  open (OPEN or PENDING) claim that no statement bound, dated within one of their holds or of a
     *  person whose retirement date the sheet's today has reached. */
    public boolean leftOutLive(Claim claim) {
        return claim.isDeferred()
                || (ClaimStatus.isOpen(claim.getStatus()) && !claim.isStated()
                        && (isRetiredReached() || holds.stream().anyMatch((h) -> h.covers(claim.getDate()))));
    }

    /** Whether a claim on this date is refused: the person is retired from a date before it, or it
     *  is dated after the from and before the to of one of their past retirements. */
    public boolean retiredBefore(java.time.LocalDate date) {
        return (retiredFrom != null && date.isAfter(java.time.LocalDate.parse(retiredFrom)))
                || retirements.stream().anyMatch((r) -> r.refuses(date));
    }

    /** Record a statement just taken: its due-total (null: n/a), date and how many claims it bound. */
    public void stated(String total, String date, int claims) {
        this.statementCount++;
        this.statedTotal = total == null ? "n/a" : total;
        this.statementDate = date;
        this.statedClaims = claims;
    }

    /** Take on the statements of a person merged into them: the count becomes theirs plus the other's;
     *  their last statement stays theirs (having none, it becomes the other's). */
    public void absorbStatements(Person from) {
        if (this.statementCount <= 0 || this.statementDate == null) {
            this.statedTotal = from.statedTotal;
            this.statementDate = from.statementDate;
        }
        this.statementCount += from.statementCount;
    }

    /** Cancel their last statement: the count goes down by one and they show the one before it
     *  (null total and date: none), keeping the cancelled one's due-total for its audit line. */
    public void unstated(String total, String date) {
        this.cancelledTotal = this.statedTotal;
        this.statementCount--;
        this.statedTotal = date == null ? null : total == null ? "n/a" : total;
        this.statementDate = date;
    }

    @JsonIgnore
    public String getCancelledTotal() { return cancelledTotal; }

    @JsonIgnore
    public int getStatedClaims() { return statedClaims; }

    @JsonIgnore
    public String getStatedAsOf() { return statedAsOf; }
    public void setStatedAsOf(String statedAsOf) { this.statedAsOf = statedAsOf; }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class PersonRepository {

    private static final String COLUMNS = "id, sheet_id, name, version, statement_count, stated_total, statement_date, retired_from, terms, contact, tags, origin";

    private static final RowMapper<Person> ROW = (rs, n) -> {
        LocalDate stated = rs.getObject("statement_date", LocalDate.class);
        LocalDate retired = rs.getObject("retired_from", LocalDate.class);
        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                null, rs.getLong("version"), rs.getInt("statement_count"),
                rs.getString("stated_total"), stated == null ? null : stated.toString());
        person.setRetiredFrom(retired == null ? null : retired.toString());
        person.setTerms(rs.getObject("terms", Integer.class));
        person.setContact(rs.getString("contact"));
        person.setTags(rs.getString("tags"));
        person.setOrigin(rs.getString("origin"));
        return person;
    };

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The end of a sheet's list: the place a person added or arriving there takes. */
    private static final String NEXT_POS = "(SELECT COALESCE(MAX(q.list_pos), 0) + 1 FROM person q WHERE q.sheet_id = ?)";

    /** The sheet's people in list order (by their place in it), each with their patrons. */
    public List<Person> list(String sheetId) {
        List<Person> people = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY list_pos, id",
                ROW, sheetId);
        Map<Long, Person> byId = new HashMap<>();
        people.forEach((p) -> byId.put(p.getId(), p));
        withGrades(sheetId, people);
        withHolds(sheetId, people);
        withAliases(sheetId, people);
        withClashing(sheetId, people);
        withRetirements(sheetId, people);
        withSnapshots(sheetId, people);
        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY added_at, patron_id",
                (rs) -> {
                    Person p = byId.get(rs.getLong("person_id"));
                    if (p != null) {
                        p.getPatronIds().add(rs.getLong("patron_id"));
                    }
                }, sheetId);
        return people;
    }

    public Person find(String sheetId, long id) {
        Person person = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id).stream().findFirst().orElse(null);
        if (person != null) {
            person.setPatronIds(new ArrayList<>(jdbc.queryForList(
                    "SELECT patron_id FROM person_patron WHERE sheet_id = ? AND person_id = ? ORDER BY added_at, patron_id",
                    Long.class, sheetId, id)));
            withGrades(sheetId, List.of(person));
            withHolds(sheetId, List.of(person));
            withAliases(sheetId, List.of(person));
            withClashing(sheetId, List.of(person));
            withRetirements(sheetId, List.of(person));
            withSnapshots(sheetId, List.of(person));
        }
        return person;
    }

    /** Whether the person was added while the sheet's today was after the date: they were not on
     *  the sheet then (one added before this was kept always was). */
    public boolean addedAfter(String sheetId, long id, LocalDate date) {
        return jdbc.queryForList("SELECT added_on FROM person WHERE sheet_id = ? AND id = ?", LocalDate.class, sheetId, id)
                .stream().anyMatch((on) -> on != null && on.isAfter(date));
    }

    /** The person as they stood at the end of the date, the date standing in for the sheet's today:
     *  the grades, holds and retirement date given them while the sheet's today was on or before it. */
    public Person findAsOf(String sheetId, long id, LocalDate asOf) {
        Person person = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id).stream().findFirst().orElse(null);
        if (person == null) {
            return null;
        }
        List<GradeFrom> grades = jdbc.query("SELECT grade, from_date FROM person_grade_history h WHERE h.sheet_id = ? "
                + "AND h.person_id = ? AND h.id = (SELECT MAX(h2.id) FROM person_grade_history h2 WHERE h2.person_id = h.person_id "
                + "AND h2.from_key = h.from_key AND (h2.on_date IS NULL OR h2.on_date <= ?)) ORDER BY from_key",
                (rs, n) -> {
                    LocalDate from = rs.getObject("from_date", LocalDate.class);
                    return new GradeFrom(rs.getString("grade"), from == null ? null : from.toString());
                }, sheetId, id, asOf);
        person.setGrades(new ArrayList<>(grades), asOf);
        person.setHolds(new ArrayList<>(jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? "
                + "AND person_id = ? AND (added_on IS NULL OR added_on <= ?) ORDER BY id", (rs, n) -> {
                    LocalDate to = rs.getObject("to_date", LocalDate.class);
                    return new Hold(rs.getObject("from_date", LocalDate.class).toString(), to == null ? null : to.toString());
                }, sheetId, id, asOf)));
        List<LocalDate> retired = jdbc.queryForList("SELECT retired_from FROM person_retired_history WHERE sheet_id = ? "
                + "AND person_id = ? AND (on_date IS NULL OR on_date <= ?) ORDER BY id DESC LIMIT 1", LocalDate.class,
                sheetId, id, asOf);
        person.setRetiredFrom(retired.isEmpty() || retired.get(0) == null ? null : retired.get(0).toString());
        person.setRetirements(new ArrayList<>(jdbc.query("SELECT from_date, to_date FROM person_retirement WHERE sheet_id = ? "
                + "AND person_id = ? AND to_date <= ? ORDER BY id", (rs, n) -> new Retirement(
                        rs.getObject("from_date", LocalDate.class).toString(), rs.getObject("to_date", LocalDate.class).toString()),
                sheetId, id, asOf)));
        return person;
    }

    /** Give each person their grades, by from-date (none first), and the one in force on the sheet's today. */
    private void withGrades(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        LocalDate today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", LocalDate.class, sheetId)
                .stream().findFirst().orElse(LocalDate.now());
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ? ORDER BY person_id, from_key",
                (rs) -> {
                    LocalDate from = rs.getObject("from_date", LocalDate.class);
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new GradeFrom(rs.getString("grade"), from == null ? null : from.toString()));
                }, sheetId);
        people.forEach((p) -> p.setGrades(grades.getOrDefault(p.getId(), new ArrayList<>()), today));
    }

    /** Give each person their holds, in the order they were added. */
    private void withHolds(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY person_id, id",
                (rs) -> {
                    LocalDate to = rs.getObject("to_date", LocalDate.class);
                    holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Hold(rs.getObject("from_date", LocalDate.class).toString(),
                                    to == null ? null : to.toString()));
                }, sheetId);
        people.forEach((p) -> p.setHolds(holds.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** Give each person their past retirements, oldest first. */
    private void withRetirements(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<Retirement>> retirements = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_retirement WHERE sheet_id = ? ORDER BY person_id, id",
                (rs) -> {
                    retirements.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Retirement(rs.getObject("from_date", LocalDate.class).toString(),
                                    rs.getObject("to_date", LocalDate.class).toString()));
                }, sheetId);
        people.forEach((p) -> p.setRetirements(retirements.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** Give each person the SNAPSHOTs written for them, oldest first. */
    private void withSnapshots(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<Snapshot>> snapshots = new HashMap<>();
        jdbc.query("SELECT person_id, day_left, due_total FROM person_snapshot WHERE sheet_id = ? ORDER BY person_id, id",
                (rs) -> {
