438	    /** The other sheets of the sheet's tree, among the sheets that exist: its ancestors (its parent,
439	     *  its parent's parent, ...) and its descendants (its children, their children, ...). */
440	    public java.util.Set<String> treeSheets(String sheetId) {
441	        java.util.Set<String> tree = new java.util.LinkedHashSet<>();
442	        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
443	        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) {
444	            tree.add(at);
445	        }
446	        List<String> below = new ArrayList<>(List.of(sheetId));
447	        java.util.Set<String> seenBelow = new java.util.HashSet<>(List.of(sheetId));
448	        for (int i = 0; i < below.size(); i++) {
449	            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting = 'parent' AND val = ?",
450	                    String.class, below.get(i))) {
451	                if (seenBelow.add(child)) {
452	                    below.add(child);
453	                    tree.add(child);
454	                }
455	            }
456	        }
457	        tree.remove(sheetId);
458	        tree.removeIf((s) -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, s) == 0);
459	        return tree;
460	    }
