462	    /** The sheet's descendants (its children, their children, ...) among the sheets that exist, by id. */
463	    public List<String> descendantSheets(String sheetId) {
464	        List<String> below = new ArrayList<>(List.of(sheetId));
465	        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
466	        for (int i = 0; i < below.size(); i++) {
467	            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting = 'parent' AND val = ?",
468	                    String.class, below.get(i))) {
469	                if (seen.add(child)) below.add(child);
470	            }
471	        }
472	        below.remove(0);
473	        below.removeIf((s) -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, s) == 0);
474	        below.sort(null);
475	        return below;
476	    }
