701	    /** Merge the person {@code from} into {@code into}: from's name and aliases become into's aliases;
702	     *  from's patrons are added to into's (not into themselves, no repeats); anyone naming from as
703	     *  patron names into instead (no repeats); into's statement count becomes theirs plus from's, their
704	     *  last statement staying theirs (having none, becoming from's), from's statements kept before
705	     *  into's; from's holds, watchers, grades and the person themselves are dropped; from's plans become into's. Their claims, pool memberships and period totals must have
706	     *  moved first. */
707	    public void merge(Person from, Person into, String user) {
708	        String sheetId = into.getSheetId();
709	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_by) VALUES (?, ?, ?, ?)",
710	                sheetId, into.getId(), from.getName(), user);
711	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
712	                into.getId(), sheetId, from.getId());
713	        for (Long patronId : from.getPatronIds()) {
714	            if (patronId != into.getId() && !into.getPatronIds().contains(patronId)) {
715	                jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_by) VALUES (?, ?, ?, ?)",
716	                        sheetId, into.getId(), patronId, user);
717	                into.getPatronIds().add(patronId);
718	            }
719	        }
720	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
721	        // Whoever named from names into instead, unless that is into themselves or they name into already.
722	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ? OR person_id IN "
723	                + "(SELECT k.person_id FROM person_patron k WHERE k.sheet_id = ? AND k.patron_id = ?))",
724	                sheetId, from.getId(), into.getId(), sheetId, into.getId());
725	        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?",
726	                into.getId(), sheetId, from.getId());
727	        into.getPatronIds().remove(Long.valueOf(from.getId()));
728	        // from's statements go before into's, so into's last stays their last.
729	        List<Long> own = jdbc.queryForList("SELECT id FROM person_statement WHERE sheet_id = ? AND person_id = ? ORDER BY id",
730	                Long.class, sheetId, into.getId());
731	        jdbc.update("UPDATE person_statement SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
732	                into.getId(), sheetId, from.getId());
733	        for (Long id : own) {
734	            jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date, taken_at) "
735	                    + "SELECT sheet_id, person_id, stated_total, statement_date, taken_at FROM person_statement WHERE id = ?", id);
736	            jdbc.update("DELETE FROM person_statement WHERE id = ?", id);
737	        }
738	        into.absorbStatements(from);
739	        saveStatements(into);
740	        for (String table : List.of("person_hold", "person_watch", "person_grade",
741	                "person_grade_history", "person_retired_history", "person_retirement")) {
742	            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
743	        }
744	        // from's plans go on making claims, now for into.
745	        jdbc.update("UPDATE plan SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId, from.getId());
746	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, from.getId());
747	        withAliases(sheetId, List.of(into));
748	    }
749	
750	    /** Move the person to the sheet {@code to} with their grades (and grade history) and aliases, their
751	     *  statements dropped (the count back to 0) and their plans going with them; their holds, watchers, patron links (either way), pool
752	     *  memberships and closed periods' fixed totals are dropped; they keep the sheet they came from as their
753	     *  origin. When {@code merging} (they are to be merged into someone there straight after) they keep
754	     *  their statements and arrive under a stand-in name, as theirs is taken there. Their claims must
755	     *  have moved first. */
756	    public void transfer(Person person, String to, boolean merging) {
757	        String sheetId = person.getSheetId();
758	        long id = person.getId();
759	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
760	        for (String table : List.of("person_hold", "person_watch", "pool_member")) {
761	            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, id);
762	        }
763	        if (merging) {
764	            jdbc.update("UPDATE person_statement SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
765	        } else {
766	            jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, id);
767	            jdbc.update("UPDATE person SET statement_count = 0, stated_total = NULL, statement_date = NULL "
768	                    + "WHERE sheet_id = ? AND id = ?", sheetId, id);
769	        }
770	        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", id);
771	        for (String table : List.of("person_grade", "person_grade_history", "person_retired_history", "person_retirement", "person_alias", "plan")) {
772	            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
773	        }
774	        String name = merging ? "#merging-" + id : person.getName();
775	        jdbc.update("UPDATE person SET sheet_id = ?, name = ?, "
776	                + "origin = ?, list_pos = " + NEXT_POS + " WHERE sheet_id = ? AND id = ?", to, name, sheetId, to, sheetId, id);
777	    }
778	
779	    /** Swap the two people's places in their sheet's list. */
780	    public void swap(String sheetId, long a, long b) {
781	        Long posA = jdbc.queryForObject("SELECT list_pos FROM person WHERE sheet_id = ? AND id = ?", Long.class, sheetId, a);
782	        Long posB = jdbc.queryForObject("SELECT list_pos FROM person WHERE sheet_id = ? AND id = ?", Long.class, sheetId, b);
783	        jdbc.update("UPDATE person SET list_pos = ? WHERE sheet_id = ? AND id = ?", posB, sheetId, a);
784	        jdbc.update("UPDATE person SET list_pos = ? WHERE sheet_id = ? AND id = ?", posA, sheetId, b);
785	    }
786	}
