181	 *  number and date, loses any figure a statement bound it to, and is listed as that person's newest
182	 *  claim. Refused (rejects) for anyone else, for a SETTLED or VOID claim, or one due by a day in a closed period. */
183	export function reassignClaim(sheetId: string, by: string, id: number, toPersonId: number): Promise<Claim> {
