190	/** The claims that count in live totals: all but the deferred claims and the open claims that no statement bound,
191	 *  dated within one of their person's holds (`to` null: open-ended) or of a person whose retirement date the sheet's
192	 *  today has reached (`retiredReached`) (SETTLED and bound claims still count). */
193	export function liveClaims(claims: Claim[],
194	  people: Array<{ id: number; holds: Array<{ from: string; to: string | null }>; retiredReached?: boolean }> | undefined): Claim[] {
195	  const byId = new Map((people ?? []).map((p) => [p.id, p]));
196	  const held = (c: Claim) => {
197	    const p = byId.get(c.personId);
198	    return !!p && (!!p.retiredReached || p.holds.some((h) => h.from <= c.date && (h.to === null || c.date <= h.to)));
199	  };
200	  return claims.filter((c) => !c.deferred && !(isOpen(c) && !c.stated && held(c)));
201	}
