203	/** Whether a person is active: one of their claims that count (`live`, see `liveClaims`) is open (OPEN or
204	 *  PENDING) and dated within the 30 days up to and including the sheet's `today`. */
205	export function isActive(live: Claim[], today: string): boolean {
206	  if (today === '') return false;
207	  const since = new Date(`${today}T00:00:00Z`);
208	  since.setUTCDate(since.getUTCDate() - 29);
209	  const from = since.toISOString().slice(0, 10);
210	  return live.some((c) => isOpen(c) && from <= c.date && c.date <= today);
211	}
