213	/** A person's patrons' shares (in hundredths, of 100.00), in the order named: 100.00 split equally, each share
214	 *  rounded half to even to two decimals, the remainder (100.00 less the shares added up) to the first-named. */
215	export function patronShares(patronIds: number[]): Array<{ id: number; share: number }> {
216	  const n = patronIds.length;
217	  if (n === 0) return [];
218	  const whole = Math.floor(10_000 / n);
219	  const rest = 10_000 % n;
220	  const each = 2 * rest > n || (2 * rest === n && whole % 2 === 1) ? whole + 1 : whole;
221	  return patronIds.map((id, i) => ({ id, share: i === 0 ? 10_000 - each * (n - 1) : each }));
222	}
