224	/** A person's backing: the sum over their patrons of the patron's figure (the frozen settled figures of their
225	 *  SETTLED claims dated within the 90 days up to and including the sheet's `today`, added up) times their share
226	 *  (see `patronShares`) divided by 100, rounded half to even (0.00 with none). */
227	export function backing(claims: Claim[], patronIds: number[], today: string): string {
228	  if (today === '') return '0.00';
229	  const since = new Date(`${today}T00:00:00Z`);
230	  since.setUTCDate(since.getUTCDate() - 89);
231	  const from = since.toISOString().slice(0, 10);
232	  const figures = new Map<number, bigint>(patronIds.map((id) => [id, 0n]));
233	  for (const c of claims) {
234	    const f = figures.get(c.personId);
235	    if (f !== undefined && c.status === 'SETTLED' && c.settledDue !== null && from <= c.date && c.date <= today) {
236	      figures.set(c.personId, f + BigInt(Math.round(Number(c.settledDue) * 100)));
237	    }
238	  }
239	  // Cents times hundredths of a percent share: 1/10_000 of a cent.
240	  const product = patronShares(patronIds).reduce((t, p) => t + (figures.get(p.id) ?? 0n) * BigInt(p.share), 0n);
241	  const cents = halfEven(product < 0n ? -product : product);
242	  const signed = product < 0n ? -cents : cents;
243	  return (Number(signed) / 100).toFixed(2);
244	}
245	
246	/** A non-negative amount in 1/10_000 of a cent to cents, half to even. */
247	function halfEven(product: bigint): bigint {
248	  const whole = product / 10_000n;
249	  const rest = product % 10_000n;
250	  return rest > 5_000n || (rest === 5_000n && whole % 2n === 1n) ? whole + 1n : whole;
251	}
