253	/** Sum the amounts of the claims that count (see `counts`) exactly (in cents), shown with two decimals. */
254	export function sumAmounts(claims: Claim[]): string {
255	  const cents = claims.filter(counts).reduce((t, c) => t + Math.round(Number(c.amount) * 100), 0);
256	  return (cents / 100).toFixed(2);
257	}
