package net.officefloor.hq.app.setting;

import java.util.Arrays;
import java.util.List;
import java.util.Map;

/** The permission matrix: for each guarded action, the roles that may take it ({@code perm-<action>},
 *  a comma separated list of roles; blank: the standing rule). Approving and rejecting are not in it:
 *  they stay with stewards. */
public final class Permissions {
    public static final String OPEN = "open";
    public static final String SETTLE = "settle";
    public static final String VOID = "void";
    public static final String REASSIGN = "reassign";
    public static final String CLOSE = "close";
    public static final String REOPEN = "reopen";

    /** The key prefix of an action's entry. */
    public static final String PREFIX = "perm-";

    /** The standing rule: the roles that may take each action while its entry is blank. */
    public static final Map<String, List<String>> STANDING = Map.of(
            OPEN, List.of(Role.CLERK, Role.STEWARD),
            SETTLE, List.of(Role.CLERK, Role.STEWARD),
            VOID, List.of(Role.CLERK, Role.STEWARD),
            CLOSE, List.of(Role.CLERK, Role.STEWARD),
            REASSIGN, List.of(Role.STEWARD),
            REOPEN, List.of(Role.STEWARD));

    private Permissions() {
    }

    /** Whether the key is an action's entry in the matrix. */
    public static boolean isKey(String key) {
        return key.startsWith(PREFIX) && STANDING.containsKey(key.substring(PREFIX.length()));
    }

    /** The roles a stored entry names (blank: none). */
    public static List<String> roles(String value) {
        return value == null || value.isBlank() ? List.of()
                : Arrays.stream(value.split(",")).map(String::trim).toList();
    }

    /** Whether the user's role on the sheet may take the action. */
    public static boolean allows(String sheetId, String user, String action, RoleRepository roles,
            SettingRepository settings) {
        List<String> allowed = roles(settings.find(sheetId, PREFIX + action));
        if (allowed.isEmpty()) allowed = STANDING.get(action);
        return allowed.contains(roles.roleOf(sheetId, user == null ? "" : user));
    }
}
package net.officefloor.hq.app.setting;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

@Repository
public class RoleRepository {

    private static final RowMapper<Role> ROW = (rs, n) ->
            new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;

    public RoleRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The roles assigned on the sheet, by user name. */
    public List<Role> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                ROW, sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them covers the sheet's
     *  today, else the one assigned (clerk when none was). */
    public String roleOf(String sheetId, String user) {
        return delegatorOf(sheetId, user) != null ? Role.STEWARD : assignedRoleOf(sheetId, user);
    }

    /** The user's own role on the sheet, delegations aside: clerk when none was assigned. */
    public String assignedRoleOf(String sheetId, String user) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                ROW, sheetId, user).stream().findFirst().map(Role::role).orElse(Role.CLERK);
    }

    /** The steward who delegated the steward role to the user by a delegation covering the sheet's
     *  today (the latest, when several do); null when none does. */
    public String delegatorOf(String sheetId, String user) {
        return jdbc.queryForList("SELECT d.delegated_by FROM delegation d JOIN sheet s ON s.id = d.sheet_id "
                + "WHERE d.sheet_id = ? AND d.user_name = ? AND d.from_date <= s.today AND s.today <= d.to_date "
                + "ORDER BY d.id DESC LIMIT 1", String.class, sheetId, user).stream().findFirst().orElse(null);
    }

    /** Assign (or replace) the user's role on the sheet. */
    public Role set(String sheetId, String user, String role, String by) {
        jdbc.update("DELETE FROM sheet_role WHERE sheet_id = ? AND user_name = ?", sheetId, user);
        jdbc.update("INSERT INTO sheet_role (sheet_id, user_name, role, set_by, set_at) "
                + "VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)", sheetId, user, role, by);
        return new Role(sheetId, user, role);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Settles a claim, fixing its due: its amount at its person's grade's rate in force on its date, rounded by the sheet's policy date to
 *  two decimals (a claim bound by a statement: the figure it was bound to). With no rate the due is not
 *  fixed and stays live. Its late charge on the sheet's today is added, then the sheet's floor applied last, and fixed with it. Refused for the user who opened it or last edited it (four eyes), and for a claim
 *  that is not OPEN, and for a role the permission matrix does not let settle. Settled by a clerk when the due is above the sheet's clerk limit (a due that is n/a is within any limit; a steward settles
 *  anything), it goes to PENDING instead (after the proof threshold: one above it with no proofs is refused), nothing fixed, until a steward approves or rejects it. */
public class SettleClaim {
    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            PersonRepository people, RateRepository rates, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, SheetRepository sheets)
            throws ClaimStatusException, PeriodClosedException {
        settle(by, claim, people, rates, periods, roles, settings, sheets);
        // Settled one at a time: in no batch.
        claim.setSettleBatch(null);
    }

    /** The rules of settling one claim, shared with {@link BulkSettleClaims}: moves the claim (unsaved) or throws. */
    static void settle(String by, Claim claim, PersonRepository people, RateRepository rates,
            PeriodRepository periods, RoleRepository roles, SettingRepository settings, SheetRepository sheets)
            throws ClaimStatusException, PeriodClosedException {
        if (!Permissions.allows(claim.getSheetId(), by, Permissions.SETTLE, roles, settings)) {
            throw new ClaimStatusException("Your role may not settle a claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        if (!ClaimStatus.OPEN.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be settled");
        }
        if (claim.isDeferred()) {
            throw new ClaimStatusException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
        }
        ClaimStatus settled = ClaimStatus.OPEN.moveTo(ClaimStatus.SETTLED);
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(by == null ? "" : by)) {
            throw new ClaimStatusException("The user who opened a claim cannot settle it");
        }
        if (claim.getEditedBy() != null && claim.getEditedBy().equals(by == null ? "" : by)) {
            throw new ClaimStatusException("The user who last edited a claim cannot settle it");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        Rate rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()),
                LocalDate.parse(claim.getDate()));
        // A claim bound by a statement settles at the figure it was bound to.
        // Its late charge on the sheet's today is frozen in.
        Dues.Late late = settings.late(claim.getSheetId(), sheets.today(claim.getSheetId()));
        String due = Dues.shown(claim, rate == null ? null : Dues.of(claim.getAmount(), rate.pct(),
                late.rounding(claim.getRoundDate())), settings.floor(claim.getSheetId()).on(claim.getDate()), late);
        requireProof(claim, person, due, settings);
        if (due != null && Role.CLERK.equals(roles.roleOf(claim.getSheetId(), by == null ? "" : by))) {
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            if (limit != null && new BigDecimal(due).compareTo(limit) > 0) {
                claim.setStatus(ClaimStatus.OPEN.moveTo(ClaimStatus.PENDING).name());
                return;
            }
        }
        claim.setStatus(settled.name());
        claim.setSettledDue(due);
    }

    /** Refuses settling or approving a claim with no proofs whose due (null: n/a, never above) is above
     *  the proof threshold in force on the claim's date: its person's grade's (the grade in force on that
     *  date) when one is set, else the sheet's. */
    static void requireProof(Claim claim, Person person, String due, SettingRepository settings) throws ClaimStatusException {
        if (due == null || claim.getProofs() > 0) return;
        BigDecimal threshold = settings.proofThreshold(claim.getSheetId(),
                person == null ? null : person.gradeOn(claim.getDate()), claim.getDate());
        if (threshold != null && new BigDecimal(due).compareTo(threshold) > 0) {
            throw new ClaimStatusException("A claim whose due is above the proof threshold needs a proof");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Approves a PENDING claim: it becomes SETTLED, its due fixed at the figure it shows at that moment
 *  (its live figure, a statement does not bind a PENDING claim, with its late charge on the sheet's
 *  today). Refused unless the user is a steward, and for the user who opened it or last edited it, and for one
 *  with no proofs whose due is above the proof threshold in force on its date. */
public class ApproveClaim {
    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            PersonRepository people, RateRepository rates, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, SheetRepository sheets)
            throws ClaimStatusException, PeriodClosedException {
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        String user = by == null ? "" : by;
        if (!ClaimStatus.PENDING.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be approved");
        }
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
            throw new ClaimStatusException("Only a steward can approve a claim");
        }
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new ClaimStatusException("The user who opened a claim cannot approve it");
        }
